package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("review_flags") @CompoundIndex(name="review_flag_user_unique",def="{'reviewId':1,'userId':1}",unique=true) public class ReviewFlag { public enum Reason { SPAM, OFFENSIVE, FAKE_REVIEW, INAPPROPRIATE, OTHER } @Id private String id;@Indexed private String reviewId;@Indexed private String userId;private Reason reason;private Instant createdAt=Instant.now();public String getId(){return id;}public String getReviewId(){return reviewId;}public void setReviewId(String x){reviewId=x;}public String getUserId(){return userId;}public void setUserId(String x){userId=x;}public Reason getReason(){return reason;}public void setReason(Reason x){reason=x;}public Instant getCreatedAt(){return createdAt;} }
